CREATE VIEW vw_conditional_affinity_normalized AS WITH scored AS (SELECT gcs.GameKey, gcs.GameID, gcs.GameTitle, gcs.avg_conditional_similarity, gcs.max_conditional_similarity, (percent_rank() OVER (ORDER BY gcs.avg_conditional_similarity) * 100.0) AS conditional_affinity_percentile FROM vw_game_conditional_similarity AS gcs)SELECT GameKey, GameID, GameTitle, avg_conditional_similarity, max_conditional_similarity, round(conditional_affinity_percentile, 2) AS conditional_affinity_percentile FROM scored;
